export class FlatRound implements MapSource {
  /** Der Bauplan und der Stand — als Felder, weil `MapSource` die Namen als Methoden braucht. */
  readonly house: HouseSpec;
  readonly haunt: HauntState;
  readonly graph: StationGraph;
  /**
   * **Dieselbe Station, wie das Monster sie kennt** (`roomGraph.monsterGraph`)
   * — ohne die Einsatzzentrale und ohne die Schleuse dorthin. Alles, was für
   * das Monster entscheidet, fragt diese Karte; alles, was für den Techniker
   * entscheidet, die andere.
   */
  readonly prowl: StationGraph;
  readonly player: Actor;
  readonly monster: Actor;
  /** Kabinen, Anzug, Sauerstoff — die Rundenregeln (`rules/roundRules.ts`). */
  readonly rules = new RoundRules(() => this.haunt);
  /** Das Lüftungsnetz, die Fahrt des Monsters darin und der Lotse der KI (`vents/`). */
  readonly vents: VentNet;
  readonly ventRide: VentTravel;
  private readonly ventPilot: VentPilot;
  /** Ein Spieler am Steuer des Monsters (`monster/`); `null` oder inaktiv heißt: die Routine. */
  driver: MonsterDriver | null = null;
  /**
   * **Wer hören will, wenn eine Lampe flackert oder ausgeht** — die 3D-Welt,
   * die daraus einen Klang im Raum macht (`HauntingWorld.lampSound`). Die
   * Meldungen an den Spieler kommen weiter als Ereignisse.
   */
  onLamp: ((kind: 'flicker' | 'out', room: string) => void) | null = null;
  /** Wie viele Reparaturen zuletzt fertig waren — daran hängt der Schub des Monsters (`noticeRepairs`). */
  private repaired = 0;
  /** Welche Werkzeuge man hat, in Reihenfolge des Durchschaltens. */
  readonly tools: string[] = ['flashlight'];
  active = 0;
  torch = true;
  /** Die Reparatur, deren Rätsel gerade offen ist. */
  puzzle: Repair | null = null;
  mode: VisibilityMode;
  /** Das letzte Sichtbarkeitsfeld — aus `step`, für die Karte. */
  field: VisibilityField;
  private snapshotCache: MapSnapshot | null = null;
  /**
   * **Der Handgriff, der gerade läuft** (`rules/chore.ts`) — heute nur das
   * Aufklappen einer Kiste. `null` heißt: Die Hände sind frei.
   */
  private chore: Chore | null = null;
  private readonly cargo: Cargo[] = [];
  private readonly consoles: Console[] = [];
  private readonly lockers: Locker[] = [];
  private readonly routine: MonsterRoutine;
  /**
   * **Das Gedächtnis des Monsters** (`monster/monsterMemory.ts`) — dasselbe
   * Stück wie im Headset, damit die 2D-Runde und die Station kein
   * unterschiedlich kluges Vieh haben. Geschrieben wird es in der Routine;
   * von hier kommt nur, was die Routine nicht sehen kann.
   */
  private readonly brain: MonsterMemory;
  /** Die Reisezeitauskunft für die Abfangrechnung — einmal je Runde gebaut. */
  private readonly estimator: ReturnType<typeof graphEstimator>;
  /**
   * **Die Blutspur des Technikers** (`rules/blood.ts`). Ihre Tropfenliste
   * *ist* `haunt.blood` — dasselbe Feld, nicht eine Kopie davon: Zwei Listen
   * wären zwei Spuren, und die gezeichnete wäre irgendwann eine andere als
   * die, über die das Monster läuft.
   */
  readonly blood: Trail = freshTrail();
  /** Wann das Monster zuletzt geschnüffelt hat — `SNIFF_EVERY` Sekunden später wieder. */
  private sniffed = -Infinity;
  /**
   * **Die Puste des Technikers** (`mission.ts`). Ohne sie war der Sprint hier
   * unbegrenzt, und damit war jede Jagd in dem Moment vorbei, in dem er
   * losrannte.
   */
  private readonly stamina = freshStamina();
  /**
   * **Der Läufer des Monsters** (`monster/monsterWalk.ts`) — dasselbe Stück
   * wie im Headset: Rasterweg, Umwegabwägung, Warten und Ziehen an der Tür.
   */
  private readonly walk: MonsterWalk;
  private decision: RoutineOutput | null = null;
  /**
   * **Was das Monster wahrnimmt** — die Alarmleiter aus `threat.ts`, und
   * zwar **die im Stand** (`HauntState.crew.threat`): Das Schiff liest daraus
   * Absicht und Jagd für Tafel und Zuschauer (`ShipExperience`), und über die
   * Leitung geht sie mit dem Stand an alle Geräte. Eine Leiter, nicht zwei.
   */
  private readonly memory: ThreatState;
  /** Das Hörmodell (`audio/hearing.ts`) und die Geräusche des Spielers seit dem letzten Schritt. */
  private readonly hearing = new Hearing();
  private pendingNoises: NoiseSource[] = [];
  /** Die Geräusche der letzten Sekunden, für die Karte (`MapNoise`). */
  private readonly noiseLog: MapNoise[] = [];
  private noiseSerial = 0;
  private stepPulse = 0;
  private monsterPulse = 0;
  /** Wer welche Tür gesperrt hat, und wie lange zugefallene halten (`rules/doorLocks.ts`). */
  readonly locks: DoorLocks = freshLocks();
  /**
   * **Welche Lampen die Tafel angemacht hat** (`rules/lamps.ts`) — höchstens
   * zwei, und keine für immer.
   *
   * Die 2D-Runde führte diese Buchführung lange nicht, weil sie hell begann:
   * Es gab keine geschaltete Lampe, nur vierzehn brennende. Seit sie dunkel
   * beginnt, ist jedes Licht hier ein geschaltetes — und es gelten dieselben
   * Regeln wie im Headset, aus derselben Datei. `switchLight` und der Spuk
   * gehen beide hier hindurch.
   */
  readonly lampBook: Lamps = freshLamps();
  /** Welches Schott gerade grundlos offen steht (`rules/doorGlitch.ts`). */
  private readonly glitch: DoorGlitch;
  /** Die Türautomatik des Schiffs — dasselbe Stück, dieselben Zahlen (`stepDoors`). */
  private readonly automaticDoors = new AutomaticDoors();
  /** Die Türen, deren Blatt gerade zu ist — für das Zellgitter eine Wand (`closedDoors`). */
  private closed: string[] = [];
  /**
   * **Die Station auf dem Zellgitter** (`stationCells.ts`) — dasselbe System
   * wie in jeder Welt: Techniker und Monster stehen auf 2 × 2 halben Kacheln,
   * und ob ein Schritt geht, entscheidet allein das Gitter.
   */
  private readonly cells: StationCells;
  /** Die Tür, die hinter dem fliehenden Techniker zufällt (`rules/doorSeal.ts`). */
  private readonly seal: DoorSeal = freshSeal();
  /** In welchem Raum er im letzten Bild stand — daran hängt „ist er durch eine Tür?". */
  private wasSpace = COMMAND;
  /** Wie viele mitspielen: entscheidet über die Wartezeit bis zum Riegel. */
  private readonly players: number;
  /** Die Wegsuche des Spielers zum nächsten Ziel — nur, wenn jemand den Weg sehen will. */
  private playerNav: FlatNavigator | null = null;
  private readonly rng: Rng;
  private tuning: BotTuning;
  private spooking: Spook = freshSpook();
  private moving = false;
  private sprinting = false;
  private seen = false;
  private caught = '';
  private radarPing = 0;
  private readonly litCache = new LitCache();
  private events: FlatEvent[] = [];
  /**
   * **Wie genau der Techniker sein Ziel genannt bekommt**
   * (`rules/roundSetup.goalPrecision`). Ohne jede Angabe ist es die Kiste: Wer
   * eine Runde ohne Verteilung aufmacht — jeder Test, jede Vorführung —, spielt
   * allein, und allein ruft einem niemand zu, welche der drei die richtige ist.
   */
  readonly precision: GoalPrecision;

  constructor(seed: number, options: FlatOptions = {}) {
    const resume = options.resume ?? null;
    this.house = generateHouse(seed, 14);
    this.graph = stationGraph(this.house);
    this.cells = new StationCells(this.house);
    this.players = options.players ?? (options.setup ? crewSize(options.setup) : CREW_SIZE);
    // **Ohne Archiv kein Ziel** (`rules/roundSetup.goalPrecision`): kein
    // Dreieck am Rand, keine Liste. Wer die Fähigkeit nicht hat, hört, wo es
    // liegt (`rules/archiveRadio.ts`), oder sucht.
    this.precision = options.setup
      ? goalPrecision(options.setup)
      : options.powers && !options.powers.archive
        ? 'none'
        : 'crate';
    this.tuning = options.tuning ?? DEFAULT_TUNING;
    this.mode = options.mode ?? 'realistic';
    // **Der laufende Stand schlägt die Optionen.** Wer eine Runde fortsetzt,
    // hat sein Monster und seinen Testmodus längst gewählt; die Optionen
    // dieser Ansicht wären daneben eine zweite Wahrheit.
    const crewOptions = resume
      ? resume.state.crew.options
      : stationOptions({
          monster: options.monster ?? 'stalker',
          test: !!options.test,
        });
    // **Der Test-Zustand** (`FlatOptions.phase`): keine Uhr, kein Treffer,
    // und die ganze Station hell — jede Lampe steht in `lit`, ohne Buchführung
    // und ohne Frist. Erst die Mission (`FlatMode.startMission`) macht das
    // Licht aus und lässt die Uhr laufen.
    const idle = !resume && options.phase === 'briefing';
    // Der Stand wird **übernommen** und nicht kopiert (`FlatResume`): Der
    // Gastgeber schreibt danach denselben Stand fort, den die Runde rechnet.
    this.haunt = resume?.state ?? {
      seed,
      phase: idle ? 'briefing' : 'running',
      crew: freshCrew(crewOptions),
      time: 0,
      monsterOn: !options.test,
      monster: null,
      shut: [],
      // **Die Station beginnt dunkel** — wie die Mission im Headset
      // (`HauntingWorld.startMission`). Eine 2D-Runde, die mit vierzehn
      // brennenden Lampen anfing, hatte die Taschenlampe zur Zierde und die
      // Tafel zum Lichtschalter gemacht: Es gab nichts einzuschalten, nur
      // etwas auszuschalten. Licht macht jetzt auch hier, wer einen Schalter
      // umlegt, höchstens zwei Räume gleichzeitig und nicht für immer
      // (`rules/lamps.ts`). **Im Test dagegen ist alles hell.**
      lit: idle ? spacesOf(this.house).map((room) => room.id) : [],
      fuse: false,
      taken: [],
      done: [],
      destroyed: [],
      technician: null,
      ride: 'out',
      ghosts: freshGhosts(),
      blood: this.blood.drops,
    };
    this.repaired = this.haunt.done.length;
    // **Eine Spur, nicht zwei.** Die Tropfenliste des Standes *ist* die der
    // Buchführung — auch nach einer Übernahme, sonst malte die Karte eine
    // Spur und das Monster liefe über eine andere.
    if (resume) {
      this.blood.drops = this.haunt.blood ?? [];
      this.haunt.blood = this.blood.drops;
      // Das Gedächtnis erst unten, wenn es steht (`loadMemory`).
      this.loadBooks({
        locks: resume.locks,
        spook: resume.spook,
        trail: resume.trail,
        lamps: resume.lamps,
      });
      // Die Werkzeuge stehen nicht im Stand, sondern im Gepäck: Was der
      // Techniker aufgesammelt hat, hat er auch nach dem Wechsel in der Hand.
      for (const id of this.haunt.crew.inventory)
        if (id in TOOL_LABELS && !this.tools.includes(id)) this.tools.push(id);
    }
    this.memory = this.haunt.crew.threat;
    this.rng = new Rng((seed ^ ((options.roll ?? 0) * 0x9e3779b1)) >>> 0);
    this.routine = new MonsterRoutine(this.tuning.monster);
    // **Die Karte des Monsters** (`roomGraph.monsterGraph`): dieselbe Station
    // ohne die Einsatzzentrale. Gedächtnis, Reisezeiten, Routine und die
    // Wegsuche des Monsters hängen daran; der Techniker behält `this.graph`
    // und läuft weiter hinein und hinaus.
    this.prowl = monsterGraph(this.house);
    this.brain = new MonsterMemory(this.prowl, () =>
      shutPairs(this.house.doors, this.haunt.shut, COMMAND),
    );
    this.estimator = graphEstimator(this.prowl);
    this.walk = new MonsterWalk(this.house, this.prowl, MONSTER_RADIUS, {
      shut: () => this.haunt.shut,
      release: (door, time) => {
        this.haunt.shut = releaseLock(this.locks, this.haunt.shut, door.id, time);
      },
      pry: (door, time) => {
        const out = pryLock(this.locks, this.haunt.shut, door.id, time, () => this.rng.next());
        this.haunt.shut = out.shut;
        return { tries: out.tries > 0, opened: out.opened };
      },
    });
    this.glitch = freshGlitch(() => this.rng.next());
    this.vents = new VentNet(this.house);
    this.ventRide = new VentTravel(this.vents);
    this.ventPilot = new VentPilot(
      this.vents,
      this.ventRide,
      MONSTERS.find((m) => m.id === crewOptions.monster)?.vent ?? 28,
      monsterBase(crewOptions.monster) * this.tuning.monster.speed,
    );
    // **Wo die beiden stehen.** Eine neue Runde setzt den Techniker vor die
    // Zentrale und das Monster ans andere Ende; eine fortgesetzte stellt beide
    // dorthin, wo sie im Augenblick des Wechsels standen.
    const at = resume ? (this.haunt.technician ?? { x: COMMAND_HOME.x, z: COMMAND_HOME.z }) : null;
    this.player = at
      ? { x: at.x, z: at.z, yaw: resume?.yaw ?? this.haunt.technician?.yaw ?? 0, space: COMMAND }
      : { x: COMMAND_HOME.x, z: COMMAND_HOME.z, yaw: 0, space: COMMAND };
    if (at) this.player.space = this.graph.spaceAt(this.player) || COMMAND;
    this.wasSpace = this.player.space;
    const carried = resume ? this.haunt.monster : null;
    const start = carried
      ? this.graph.spaceAt(carried) || COMMAND
      : farthest(this.graph, this.player);
    const centre = carried ?? this.graph.centre(start);
    this.monster = { x: centre.x, z: centre.z, yaw: 0, space: start };
    if (this.haunt.monsterOn) this.haunt.monster = { x: centre.x, z: centre.z };
    // Das Gedächtnis nachspielen, sobald es eines gibt (`net.loadMemory`).
    if (resume?.memory) this.loadMemory(resume.memory);

    const layout = stationLayout(this.house);
    // Inhalt und Kennzeichen kommen aus `rules/cargo.ts` — dieselbe Liste, aus
    // der auch das Schiff seine Frachtschränke baut. Früher würfelte jede Welt
    // für sich, und das ging genau so lange gut, wie jeder Raum eine Kiste hatte.
    for (const slot of cargoOf(this.house)) {
      const cargo = layout.find((p) => p.id === slot.id);
      if (!cargo) continue;
      this.cargo.push({
        id: slot.id,
        roomId: slot.roomId,
        at: cargo.approach,
        loot: slot.loot.kind === 'empty' ? '' : cargoKey(slot),
        label: lootName(this.house, slot),
        mark: cargoLabel(slot),
        badge: slot.mark,
        key: cargoKey(slot),
        empty: slot.loot.kind === 'empty',
      });
    }
    for (const room of this.house.rooms) {
      const locker = layout.find((p) => p.id === `locker-${room.id}`);
      if (locker) this.lockers.push({ id: room.id, roomId: room.id, at: locker.approach });
    }
    for (const repair of repairsFor(this.house)) {
      const console = layout.find((p) => p.id === `console-${repair.id}`);
      if (console)
        this.consoles.push({ id: console.id, repair, roomId: repair.roomId, at: console.approach });
    }
    this.field = computeVisibility(
      { snapshot: this.snapshot(), mode: this.mode, viewerId: PLAYER_ID },
      this.litCache,
    );
  }

  /**
   * **Die Buchführung nachträglich übernehmen** — Riegel, Spuk, Wunde und das
   * Gedächtnis des Monsters (`FlatResume` ohne den Stand).
   *
   * Der Konstruktor ruft es für eine fortgesetzte Runde; die Welt ruft es noch
   * einmal, wenn die Bücher **nach** dem Öffnen eintreffen: Wer die Seite
   * mitten in der Mission neu lädt und wieder an den Stock geht, kennt den
   * Stand vom Gastgeber (er reist alle paar Hundertstel über die Leitung), die
   * Bücher aber nicht — die schickt der alte Gastgeber erst mit der Übergabe
   * (`net.handoverMessage`), und die kommt, wenn diese Runde schon läuft.
   * Was fehlt, fängt bis dahin von vorn an; was kommt, gilt.
   */
  loadBooks(books: Pick<FlatResume, 'locks' | 'spook' | 'trail' | 'memory' | 'lamps'>): void {
    if (books.trail) {
      this.blood.until = books.trail.until;
      this.blood.from = books.trail.from ? { ...books.trail.from } : null;
      this.blood.walked = books.trail.walked;
    }
    if (books.locks) {
      this.locks.chosen = books.locks.chosen;
      this.locks.until = books.locks.until;
      this.locks.slams = books.locks.slams.map((one) => ({ ...one }));
      this.locks.pries = books.locks.pries.map((one) => ({ ...one }));
      this.locks.cooling = books.locks.cooling.map((one) => ({ ...one }));
    }
    if (books.spook) this.spooking = { ...books.spook };
    if (books.lamps) this.lampBook.on = books.lamps.on.map((one) => ({ ...one }));
    if (books.memory) this.loadMemory(books.memory);
  }

  /** Das Gedächtnis des Monsters nachspielen (`net.loadMemory`). */
  private loadMemory(memory: MonsterBook): void {
    loadMemory(this.brain, memory, (point) => this.graph.spaceAt(point));
  }

  /**
   * **Die Buchführung dieser Runde, zum Mitnehmen** — die Gegenseite von
   * `FlatResume`.
   *
   * Wer die Ansicht wechselt (2D → 3D) oder den Gastgeber übergibt, braucht
   * genau das, was *nicht* im `HauntState` steht: Riegel, Spuk, Wunde und das
   * Gedächtnis des Monsters. Die Sperren gehen dabei als **Abschrift** heraus
   * und nicht als dasselbe Objekt: Wer weitergibt, gibt nicht auch noch einen
   * Draht zurück in eine Runde, die er gerade schließt.
   */
  books(): { locks: DoorLocks; spook: Spook; trail: TrailBook; memory: MonsterBook; lamps: Lamps } {
    return {
      locks: {
        chosen: this.locks.chosen,
        until: this.locks.until,
        slams: this.locks.slams.map((one) => ({ ...one })),
        pries: this.locks.pries.map((one) => ({ ...one })),
        cooling: this.locks.cooling.map((one) => ({ ...one })),
      },
      spook: { ...this.spooking },
      trail: {
        until: this.blood.until,
        from: this.blood.from ? { ...this.blood.from } : null,
        walked: this.blood.walked,
      },
      memory: packMemory(this.brain, this.graph.spaces),
      lamps: { on: this.lampBook.on.map((one) => ({ ...one })) },
    };
  }

  get phase(): HauntState['phase'] {
    return this.haunt.phase;
  }

  /**
   * **Ob die Mission läuft** — im Gegensatz zum Test-Zustand davor und danach
   * (`FlatOptions.phase`): Dort rechnet der Schritt weiter (Laufen, Türen,
   * ein Mensch am Steuer des Monsters), aber ohne Uhr, Spuk und Treffer.
   */
  get live(): boolean {
    return this.haunt.phase === 'running';
  }

  /** Ob überhaupt gerechnet wird: Mission oder Test — nicht nach dem Ende. */
  private get stepping(): boolean {
    return this.haunt.phase === 'running' || this.haunt.phase === 'briefing';
  }

  get activeTool(): string {
    return this.tools[this.active] ?? '';
  }

  /** Was gerade vor dem Spieler liegt — für die Beschriftung des Knopfs. */
  get target(): { kind: MapItem['kind'] | 'door' | 'light'; id: string; label: string } | null {
    const near = this.nearest();
    if (!near) return null;
    return { kind: near.kind, id: near.id, label: near.label };
  }

  /** Die Meldungen seit dem letzten Abholen. */
  drain(): FlatEvent[] {
    const out = this.events;
    this.events = [];
    return out;
  }

  setMode(mode: VisibilityMode): void {
    this.mode = mode;
  }

  // --- MapSource ------------------------------------------------------------

  lamps(): ReadonlyArray<{ id: string; x: number; z: number; intensity: number }> {
    return spacesOf(this.house).map((room) => {
      const centre = this.graph.centre(room.id);
      return { id: room.id, x: centre.x, z: centre.z, intensity: 1 };
    });
  }

  doorOpen(id: string): boolean {
    return this.automaticDoors.isOpen(id);
  }

  /**
   * **Die automatischen Türen, einmal je Bild** — und mit Nachlauf: Wer genau
   * auf der Auslöseweite steht, ließe ein Blatt sonst je Bild auf- und
   * zufahren, und jedes davon wäre ein Geräusch.
   *
   * **Ein Blatt, das fährt, ist zu hören** (`MapNoiseCause` `door`): Für den,
   * der es sieht, sagt die Welle nur, dass da eine Tür ging — nicht, wer
   * hindurchging. Genau darum geht es: Ein Geräusch ist ein Geräusch.
   */
  /**
   * **Dieselbe Türautomatik wie im Schiff** (`automaticDoors.ts`): ein
   * Kasten vor der Tür statt eines Kreises, ein Nachlauf in Sekunden statt
   * in Metern, und ein belegter Durchgang, der nie um jemanden herum zufällt.
   * Lange hatte die 2D-Runde ihre eigene Rechnung (Radius 2,2 m, Nachlauf bis
   * 2,6 m) — ein Türblatt, das hier offen stand und dort zu war, war für das
   * Gehör und die Sicht des Monsters ein anderes Türblatt.
   */
  /**
   * **Wer außer Techniker und Monster vor einer Tür steht** — der Monster-Anzug
   * ohne laufende Runde (`HauntingWorld.monsterWalkers`). Die Tür fährt für ihn
   * auf wie für den Techniker.
   */
  guests: FloorPoint[] = [];

  private stepDoors(dt: number): void {
    // **Ab und zu fährt ein Schott von selbst auf** (`rules/doorGlitch.ts`) —
    // ein Stationsfehler, damit ein fahrendes Blatt nicht länger heißt „da ist
    // jemand". Gesperrte Schotts sind nicht dabei, und zufahren tut es wie
    // jedes andere: erst, wenn niemand mehr davorsteht.
    const faulty = stepGlitch(
      this.glitch,
      leafDoors(this.house)
        .filter((door) => !this.haunt.shut.includes(door.id))
        .map((door) => door.id),
      this.haunt.time,
      () => this.rng.next(),
    );
    if (faulty.opened) this.events.push({ kind: 'info', text: 'Irgendwo fährt ein Schott auf.' });
    const occupants: FloorPoint[] = [{ x: this.player.x, z: this.player.z }, ...this.guests];
    if (this.haunt.monsterOn && !this.ventRide.concealed)
      occupants.push({ x: this.monster.x, z: this.monster.z });
    for (const door of leafDoors(this.house)) {
      const at = doorCentre(door);
      const edge = { x: at.x, z: at.z, alongX: doorAxis(door.dir) === 'x' };
      const ghosts = door.id === faulty.id ? [...occupants, { x: at.x, z: at.z }] : occupants;
      const was = this.automaticDoors.isOpen(door.id);
      const open = this.automaticDoors.step(
        door.id,
        edge,
        this.haunt.shut.includes(door.id),
        ghosts,
        dt,
      );
      if (open !== was) this.wave('', at, NOISE.door, 'door');
    }
    this.closed = this.closedDoors();
  }

  /**
   * **Was gerade wirklich im Weg steht**: jede Tür, deren Blatt zu ist — die
   * gesperrten und die, vor denen niemand steht. Im Schiff ist ein zugefahrenes
   * Blatt ein Collider; hier ist es dasselbe, eine Wand für `slide`.
   */
  private closedDoors(): string[] {
    return leafDoors(this.house)
      .filter((door) => !this.automaticDoors.isOpen(door.id))
      .map((door) => door.id);
  }

  /**
   * **Die Uhr an dieser Tür** (`rules/doorLocks.ts`): Solange sie gesperrt
   * ist, wie lange die Sperre noch hält; danach, wie lange sie noch offen
   * bleiben **muss**. Beides wird derselbe Balken über der Tür, rot das eine,
   * grün das andere (`map/flatScene.ts`, `map/mapView.ts`).
   */
  doorHold(id: string): { left: number; total: number; cooling?: boolean } | null {
    if (this.haunt.shut.includes(id)) {
      const until = holdUntil(this.locks, id);
      if (until === null) return null;
      const total = this.locks.chosen === id ? HOLD_RANGE[1] : SLAM_HOLD;
      return { left: Math.max(0, until - this.haunt.time), total };
    }
    const warm = coolingUntil(this.locks, id);
    const left = warm === null ? 0 : warm - this.haunt.time;
    return left > 0 ? { left, total: LOCK_COOLDOWN, cooling: true } : null;
  }

  entities(): readonly MapEntity[] {
    const kind = this.haunt.crew.options.monster;
    const profile = ENTITY_PROFILES[kind];
    const out: MapEntity[] = [
      {
        id: PLAYER_ID,
        kind: 'player',
        label: 'Techniker',
        at: { x: this.player.x, z: this.player.z },
        yaw: this.player.yaw,
        roomId: this.player.space,
        concealed: !!this.haunt.crew.hidden,
        moving: this.moving,
        sprinting: this.sprinting,
        held: this.activeTool,
        sense: { fov: BOT_FOV, range: BOT_VISION, hearing: 0 },
      },
    ];
    if (this.haunt.monsterOn)
      out.push({
        id: MONSTER_ID,
        kind: 'monster',
        label: MONSTERS.find((m) => m.id === kind)?.name ?? profile.label,
        at: { x: this.monster.x, z: this.monster.z },
        yaw: this.monster.yaw,
        roomId: this.monster.space,
        concealed: this.ventRide.concealed,
        moving: !this.ventRide.busy && (this.decision?.pace ?? 'still') !== 'still',
        sprinting: this.decision?.pace === 'hunt',
        held: '',
        sense: {
          fov: MONSTER_FOV,
          range: profile.vision * this.tuning.monster.vision,
          hearing: profile.hearing * this.tuning.monster.hearing,
        },
      });
    return out;
  }

  items(): readonly MapItem[] {
    const crew = this.haunt.crew;
    const out: MapItem[] = [];
    // **Auf einer Kiste steht ihr Kennzeichen und nicht ihr Inhalt.** Das
    // Label reiste bis hierher durch den Snapshot und damit übers Netz: Wer
    // „Kühlmittelpumpe" daraufschrieb, verriet die richtige Kiste an jeden,
    // der eine Karte offen hatte — auch dann, wenn ein Mensch am Archiv sitzt
    // und genau das seine Auskunft gewesen wäre.
    const goal = this.precision === 'crate' ? this.objectives()[0] : null;
    for (const cargo of this.cargo) {
      const taken = crew.inventory.includes(cargo.key) || this.haunt.done.includes(cargo.key);
      out.push({
        id: cargo.id,
        kind: 'cargo',
        label: cargo.mark,
        roomId: cargo.roomId,
        at: { ...cargo.at },
        state: taken ? 'taken' : crew.opened.includes(cargo.id) ? 'open' : 'closed',
        interactive: !taken,
        mark: { colour: cargo.badge.colour, number: cargo.badge.number },
        ...(goal?.id === cargo.id ? { goal: true } : {}),
      });
    }
    for (const console of this.consoles) {
      const solved = this.haunt.done.includes(console.repair.itemId);
      out.push({
        id: console.id,
        kind: 'console',
        label: console.repair.title,
        roomId: console.roomId,
        at: { ...console.at },
        state: solved ? 'solved' : 'broken',
        interactive: !solved,
      });
    }
    for (const locker of this.lockers)
      out.push({
        id: `locker-${locker.id}`,
        kind: 'locker',
        label: 'Schutzschrank',
        roomId: locker.roomId,
        at: { ...locker.at },
        state: !this.rules.cabinUsable(locker.id)
          ? 'destroyed'
          : crew.hidden === locker.id
            ? 'open'
            : 'locked',
        interactive: this.rules.cabinUsable(locker.id),
      });
    out.push({
      id: 'van',
      kind: 'van',
      label: 'Einsatzzentrale',
      roomId: COMMAND,
      at: { x: COMMAND_HOME.x, z: COMMAND_HOME.z },
      state: this.haunt.done.length >= 3 ? 'ready' : '',
      interactive: false,
    });
    const open = this.ventRide.openFlap;
    out.push(...this.vents.items(open ? [open.id] : []));
    return out;
  }

  ventLinks(): MapSnapshot['ventLinks'] {
    return this.vents.mapLinks();
  }

  /** Die Geräusche der letzten Sekunden — als Wellen für die Karte. */
  noises(): MapNoise[] {
    return this.noiseLog;
  }

  carriedLights(): readonly MapLight[] {
    if (!this.torch || this.activeTool !== 'flashlight' || this.haunt.crew.hidden) return [];
    return [
      {
        id: 'torch',
        roomId: this.player.space,
        at: { x: this.player.x, z: this.player.z },
        on: true,
        radius: TORCH_RANGE,
        kind: 'torch',
        yaw: this.player.yaw,
        fov: TORCH_FOV,
        color: '#ffe9b0',
      },
    ];
  }

  spec(): HouseSpec {
    return this.house;
  }

  state(): HauntState {
    return this.haunt;
  }

  round(): MapRound {
    return this.rules.status(this.haunt);
  }

  /** Der Snapshot dieses Bildes — einmal je Schritt gerechnet. */
  snapshot(): MapSnapshot {
    if (!this.snapshotCache) this.snapshotCache = extractMapSnapshot(this, 'flat');
    return this.snapshotCache;
  }

  // --- Ein Schritt --------------------------------------------------------

  step(dt: number, input: FlatInput): void {
    let left = Math.max(0, Math.min(0.5, dt));
    // Der Schritt des Körpers (Brille) einmal je Bild, nicht je Scheibe.
    if (input.shift && this.stepping && !this.haunt.crew.hidden) {
      const to = this.cells.slide(this.closed, this.player, input.shift.x, input.shift.z);
      this.player.x = to.x;
      this.player.z = to.z;
      const space = spaceAtMetres(this.house, this.player, this.player.space, SPACE_MARGIN);
      this.player.space =
        space === null ? this.player.space : space === COMMAND ? COMMAND : space.id;
    }
    if (input.yaw !== undefined && Number.isFinite(input.yaw)) this.player.yaw = input.yaw;
    while (left > 0) {
      const slice = Math.min(MAX_STEP, left);
      left -= slice;
      this.tick(slice, input);
    }
    while (this.noiseLog.length && this.haunt.time - this.noiseLog[0]!.since > NOISE_MEMORY)
      this.noiseLog.shift();
    this.snapshotCache = null;
    this.field = computeVisibility(
      { snapshot: this.snapshot(), mode: this.mode, viewerId: PLAYER_ID },
      this.litCache,
    );
  }

  private tick(dt: number, input: FlatInput): void {
    if (!this.stepping) return;
    // **Der Test ist kein Stillstand.** Die Uhr des Standes läuft auch dort
    // weiter — Wellen, Türen und Spuren hängen an ihr —, nur zeigt sie
    // niemand als Sauerstoff an, und `rules.step` beendet nur eine Mission.
    const live = this.live;
    this.haunt.time += dt;
    const out = this.rules.step(this.haunt);
    if (out) {
      this.events.push(out);
      return;
    }
    this.radarPing = Math.max(0, this.radarPing - dt);
    const crew = this.haunt.crew;
    // Zugefallene Türen gehen von selbst wieder auf (`rules/doorLocks.ts`).
    const locks = stepLocks(this.locks, this.haunt.shut, this.haunt.time);
    if (locks.opened.length) {
      this.haunt.shut = locks.shut;
      this.events.push({ kind: 'info', text: 'Eine Tür geht wieder auf.' });
    }
    // Die abkühlenden Riegel stehen im Stand, damit die Tafel ihre Uhr zeigen
    // kann (`HauntState.cooling`) — in 2D ist das derselbe Stand, den auch das
    // Telefon liest.
    this.haunt.cooling = this.locks.cooling;
    this.haunt.held = this.locks.chosen;
    // Und die Lampen gehen von selbst wieder aus (`rules/lamps.ts`): erst das
    // Flackern als Vorwarnung, dann dunkel. Gemeldet wird nur, was im eigenen
    // Raum passiert — anderswo sieht der Techniker es ja nicht.
    const lamps = stepLamps(this.lampBook, this.haunt.lit, this.haunt.time);
    for (const room of lamps.flicker) this.onLamp?.('flicker', room);
    if (lamps.flicker.includes(this.player.space))
      this.events.push({ kind: 'warn', text: 'Die Lampe flackert.' });
    if (lamps.out.length) {
      this.haunt.lit = lamps.lit;
      for (const room of lamps.out) this.onLamp?.('out', room);
      if (lamps.out.includes(this.player.space))
        this.events.push({ kind: 'warn', text: 'Das Licht geht aus.' });
    }
    this.stepDoors(dt);
    this.noticeRepairs();

    // --- Der laufende Handgriff ---------------------------------------------
    // **Vor der Bewegung.** Er wird an der Stelle gemessen, an der der Spieler
    // beim letzten Bild stand; erst danach darf er einen Schritt tun. Käme der
    // Griff nach dem Schritt, wäre ein Abbruch immer ein Bild zu spät — und
    // ein Griff, der im letzten Bild fertig wird, wäre fertig, obwohl der
    // Spieler schon losgelaufen ist.
    this.stepChore(dt);

    // --- Spieler ------------------------------------------------------------
    const length = Math.hypot(input.x, input.z);
    const wants = length > 0.05 && !crew.hidden && !this.puzzle;
    this.moving = wants;
    this.sprinting = wants && input.sprint;
    // **Die Puste** (`mission.ts`): fünf Sekunden Sprint, danach Trab, beim
    // Gehen füllt sie sich wieder auf. Sie läuft auch mit, wenn niemand sich
    // bewegt — sonst hinge die Erholung daran, ob der Stock genau in der Mitte
    // steht.
    const dash = stepStamina(this.stamina, dt, this.sprinting);
    let speed = 0;
    if (wants) {
      const scale = Math.min(1, length);
      // Geduckt halb so schnell — Sprint hebt das Ducken auf (`mission.CROUCH_FACTOR`).
      const crouch = !!input.crouch && !input.sprint ? CROUCH_FACTOR : 1;
      speed = (input.sprint ? PLAYER_SPRINT_SPEED * dash : PLAYER_WALK_SPEED) * scale * crouch;
      const nx = input.x / length,
        nz = input.z / length;
      if (input.yaw === undefined) this.player.yaw = Math.atan2(-nx, -nz);
      const to = this.cells.slide(this.closed, this.player, nx * speed * dt, nz * speed * dt);
      this.player.x = to.x;
      this.player.z = to.z;
      const space = spaceAtMetres(this.house, this.player, this.player.space, SPACE_MARGIN);
      this.player.space =
        space === null ? this.player.space : space === COMMAND ? COMMAND : space.id;
      // Jeder Schritt eine Welle auf der Karte — rennend öfter und weiter.
      this.stepPulse -= dt;
      if (this.stepPulse <= 0) {
        this.stepPulse = input.sprint ? SPRINT_PULSE : STEP_PULSE;
        this.wave(PLAYER_ID, this.player, stepLoudness(speed), input.sprint ? 'sprint' : 'walk');
      }
    } else this.stepPulse = 0;
    // **Die Blutspur** (`rules/blood.ts`): Sie läuft in jedem Bild mit, auch
    // wenn niemand blutet — sonst blieben die Tropfen einer längst
    // geschlossenen Wunde bis zum Rundenende liegen.
    stepTrail(this.blood, this.player, this.haunt.time);
    // Der Abstand zählt zwischen den festen Blöcken (`blockGap`), nicht
    // zwischen den gezeichneten Stellen dazwischen.
    const gap = this.haunt.monsterOn ? blockGap(this.player, this.monster) : Infinity;
    if (live) this.stepSeal(gap);
    stepVitals(crew, dt, speed, gap);

    if (
      this.haunt.done.length >= 3 &&
      onApron(Math.floor(this.player.x / TILE), Math.floor(this.player.z / TILE))
    ) {
      this.haunt.phase = 'won';
      this.events.push({ kind: 'good', text: 'MISSION ERFÜLLT · Alle Systeme online.' });
      return;
    }

    // --- Spuk — nur in der Mission. Im Test bleibt das Licht an und keine
    // Tür fällt zu: Wer Rollen ausprobiert, soll die Station sehen.
    if (live) this.stepSpook(dt);

    if (!this.haunt.monsterOn) return;

    // --- Im Schacht: nichts hören, nichts sehen, nur fahren (`vents/ventTravel.ts`).
    const piloted = this.driver?.active() === true;
    if (this.ventRide.busy) {
      const event = this.ventRide.step(dt, this.monster, !piloted);
      if (event === 'entered' || event === 'exited')
        this.wave(MONSTER_ID, this.monster, NOISE.monsterVent, 'vent');
      this.haunt.monster = { x: this.monster.x, z: this.monster.z };
      return;
    }

    // **Im Test steht die Routine still.** Nur ein Mensch am Steuer bewegt das
    // Monster — „wenn er will" —, und getroffen wird dabei niemand: Der
    // Techniker läuft in derselben hellen Station herum und stirbt nicht.
    if (!live) {
      if (!piloted) {
        this.decision = null;
        return;
      }
      const decision = this.driver!.decide(dt);
      this.decision = decision;
      if (decision.goal)
        this.stepMonster(
          decision.goal,
          paceSpeed(monsterBase(crew.options.monster), this.tuning.monster, decision.pace, 0),
          dt,
        );
      this.haunt.monster = { x: this.monster.x, z: this.monster.z };
      this.stepMonsterNoise(decision, dt);
      return;
    }

    // --- Wahrnehmung des Monsters: Sehen über die Karte, Hören über das
    // Hörmodell, die Alarmleiter aus `threat.ts` — dieselbe wie im Headset.
    const profile = ENTITY_PROFILES[crew.options.monster];
    const hidden = !!crew.hidden;
    const snapshot = this.snapshot();
    if (this.moving && !hidden)
      this.pendingNoises.push({
        at: { x: this.player.x, z: this.player.z },
        loudness: stepLoudness(speed),
      });
    const heard = hidden
      ? []
      : hearNoises(
          this.hearing,
          snapshot,
          this.monster,
          this.pendingNoises,
          this.tuning.monster.hearing,
        );
    this.pendingNoises.length = 0;
    // **Dieselben Augen wie im Headset** (`monster/monsterSight.ts`): im
    // Licht, im Kegel, keine Wand dazwischen — oder auf Berührungsnähe.
    const { seen, lineOfSight } = monsterSight({
      snapshot,
      light: this.lightOnly(),
      monster: this.monster,
      player: this.player,
      hidden,
      range: profile.vision * this.tuning.monster.vision,
    });
    const alertBefore = this.memory.alert;
    stepAwareness(
      this.memory,
      dt,
      {
        player: this.player,
        monster: this.monster,
        noises: heard,
        flashlight: this.torch,
        lineOfSight,
        insideStation: true,
        seen,
      },
      { vision: profile.vision, memory: profile.memory * this.tuning.monster.memory },
      !hidden,
    );
    if (seen && !this.seen) this.events.push({ kind: 'bad', text: 'Es hat dich gesehen.' });
    else if (!seen && alertBefore < 2 && this.memory.alert >= 2)
      this.events.push({ kind: 'warn', text: 'Etwas horcht.' });
    else if (!seen && alertBefore < 3 && this.memory.alert >= 3 && this.memory.mode === 'hunt')
      this.events.push({ kind: 'bad', text: 'Es hat dich gehört.' });
    this.seen = seen;
    // --- Was die beiden voneinander behalten (`rules/ghosts.ts`): die
    // zuletzt gesehene Stelle. Sie hängt an genau derselben Prüfung wie die
    // Alarmleiter — ein zweiter, eigener Sichttest wäre eine zweite Wahrheit,
    // und dann zeigte der Marker woandershin als das Verhalten des Monsters.
    const ghosts = this.haunt.ghosts;
    ghosts.technician = markGhost(
      ghosts.technician,
      seen,
      this.player,
      this.player.yaw,
      this.haunt.time,
    );
    // Und andersherum: Der Techniker merkt sich das Monster genau dann, wenn
    // seine eigene Sicht es zeigt — Kegel, Licht und freie Linie stecken schon
    // im Sichtfeld der Karte (`map/visibility.ts`), das jeder Schritt ohnehin
    // rechnet. In „Alles sehen" zeigt dieses Feld alles; dann läuft der Marker
    // mit dem Monster mit, und genau das sollen Zuschauer sehen.
    ghosts.monster = markGhost(
      ghosts.monster,
      this.field.visibleEntities.includes(MONSTER_ID),
      this.monster,
      this.monster.yaw,
      this.haunt.time,
    );
    if (hidden && (seen || this.monster.space === this.player.space) && this.caught !== crew.hidden)
      this.caught = crew.hidden;
    if (!hidden) this.caught = '';

    // **Die Fährte unter den eigenen Füßen** (`rules/blood.ts`): Nur Tropfen
    // im Raum des Monsters und in Schnüffelweite zählen — quer über die
    // Station riecht niemand etwas. Was daraus wird, entscheidet die Routine
    // (`RoutineInput.scent`), die es ins Gedächtnis schreibt. Gesucht wird
    // zweimal je Sekunde und nicht je Bild: Eine Spur liegt da, sie trifft
    // nicht ein.
    let scent: Scent | null = null;
    if (!piloted && this.haunt.time - this.sniffed >= SNIFF_EVERY) {
      this.sniffed = this.haunt.time;
      scent = sniff(
        this.blood,
        this.monster,
        this.haunt.time,
        (drop) => this.prowl.spaceAt(drop) === this.monster.space,
      );
    }
    const decision = piloted
      ? this.driver!.decide(dt)
      : this.routine.step(this.prowl, {
          dt,
          at: this.monster,
          here: this.monster.space,
          signal: this.memory.memory > 0 ? this.memory.target : null,
          seen,
          quarry: this.player.space,
          caught: this.caught,
          rng: () => this.rng.next(),
          memory: this.brain,
          scent,
          estimator: this.estimator,
          base: monsterBase(crew.options.monster),
          time: this.haunt.time,
          sprinting: this.sprinting,
          stamina: { left: this.stamina.left, trot: PLAYER_SPRINT_SPEED * TROT },
          ...takeAlert(this.memory),
        });
    this.decision = decision;
    if (decision.strike && decision.cabin) {
      // Die Kabine ist danach hin (`rules/roundRules.ts`) — getroffen wird
      // nur, wer genau darin steckt; eine leere Kabine ist ein Ausweg weniger.
      this.rules.destroyCabin(decision.cabin);
      if (crew.hidden === decision.cabin) {
        this.caught = '';
        if (this.rules.cabinStrike(crew)) this.hit('Die Kabine wird aufgerissen.');
      } else this.events.push({ kind: 'warn', text: 'Irgendwo wird eine Kabine aufgerissen.' });
    }
    if (decision.cue === 'scream') {
      this.events.push({ kind: 'bad', text: 'Ein Schrei.' });
      this.wave(MONSTER_ID, this.monster, NOISE.monsterCall, 'call');
    }
    const base = monsterBase(crew.options.monster);
    if (piloted) {
      // Ein Spieler steuert direkt: kein Türrouting, kein Lotse — nur Gleiten an Wänden.
      if (decision.goal)
        this.stepMonster(
          decision.goal,
          paceSpeed(base, this.tuning.monster, decision.pace, decision.boost),
          dt,
        );
    } else {
      // Der Lotse biegt das Ziel auf eine Klappe um, wenn der Schacht lohnt (`vents/ventPilot.ts`).
      const steered = this.ventPilot.steer(decision, this.monster, this.haunt.time, this.prowl);
      if (!this.ventRide.busy)
        this.moveMonster(
          steered,
          dt,
          paceSpeed(base, this.tuning.monster, steered.pace, steered.boost),
        );
      // Wer steht und horcht, dreht sich zur Richtung des Geräuschs.
      if (decision.face && decision.pace === 'still')
        this.monster.yaw = Math.atan2(
          -(decision.face.x - this.monster.x),
          -(decision.face.z - this.monster.z),
        );
    }
    this.haunt.monster = { x: this.monster.x, z: this.monster.z };
    this.stepMonsterNoise(decision, dt);

    // **Das Monster schlägt um sich.** Wer in Reichweite steht, wird
    // getroffen — von der KI wie von einem Spieler am Steuer. Ein eigener
    // Angriffsknopf verlangte, im Moment der Berührung zu tippen, und in
    // diesem Moment schaut niemand auf seine Knöpfe (`monster/monsterHelm.ts`).
    if (gap < CONTACT && !hidden && takeCrewHit(crew, true)) this.hit('Treffer.');
  }

  /**
   * **Der Spuk der Mission** (`haunt.ts`): Das Monster macht Lampen aus und
   * wirft Türen zu — beides durch dieselbe Buchführung wie die Schalttafel,
   * damit eine gelöschte Lampe danach keine der zwei geschalteten mehr ist
   * (`rules/lamps.ts`) und eine zugefallene Tür ihre Frist hat
   * (`rules/doorLocks.ts`).
   */
  private stepSpook(dt: number): void {
    const spooked = stepHaunt(
      this.spooking,
      {
        spec: this.house,
        monster: this.haunt.monsterOn ? this.haunt.monster : null,
        lit: this.haunt.lit,
        shut: this.haunt.shut,
        // Keine Tür auf den Kopf: Wer im Durchgang steht, wird nicht
        // eingeklemmt (`haunt.slammable`).
        occupants:
          this.haunt.monsterOn && this.haunt.monster
            ? [this.player, this.haunt.monster]
            : [this.player],
      },
      dt,
    );
    this.spooking = spooked.spook;
    if (spooked.lightOut && this.haunt.lit.includes(spooked.lightOut)) {
      this.haunt.lit = lampOut(this.lampBook, this.haunt.lit, spooked.lightOut);
      if (spooked.lightOut === this.player.space)
        this.events.push({ kind: 'warn', text: 'Das Licht geht aus.' });
    }
    if (spooked.doorShut && !this.haunt.shut.includes(spooked.doorShut)) {
      this.haunt.shut = slamDoor(this.locks, this.haunt.shut, spooked.doorShut, this.haunt.time);
      this.events.push({ kind: 'warn', text: 'Irgendwo fällt eine Tür zu.' });
      const door = this.house.doors.find((d) => d.id === spooked.doorShut);
      if (door) this.wave('', doorCentre(door), NOISE.slam, 'slam');
    }
  }

  /** Die Schritte des Monsters als Wellen: leise beim Schleichen, weit beim Rennen. */
  private stepMonsterNoise(decision: RoutineOutput, dt: number): void {
    if (decision.pace === 'still') {
      this.monsterPulse = 0;
      return;
    }
    this.monsterPulse -= dt;
    if (this.monsterPulse > 0) return;
    const hunting = decision.pace === 'hunt';
    this.monsterPulse = hunting ? SPRINT_PULSE : STEP_PULSE;
    this.wave(
      MONSTER_ID,
      this.monster,
      hunting
        ? NOISE.monsterRun
        : decision.mode === 'search'
          ? NOISE.monsterStalk
          : NOISE.monsterWalk,
      'monster',
    );
  }

  /**
   * **Die Tür, die hinter dem Techniker zufällt** (`rules/doorSeal.ts`).
   *
   * Er hat gegen das Monster nur eines in der Hand, und das ist eine Tür.
   * Also fällt sie zu, wenn er verfolgt durch sie hindurchgeht — allein macht
   * er das selbst und sofort, mit einer Zentrale im Rücken muss er es
   * **sagen**, und bis das gehört und gedrückt ist, vergehen ein bis zwei
   * Sekunden. Steht das Monster dann schon mit im Raum, war es umsonst: Ein
   * Riegel hinter dem Verfolger ist keiner.
   *
   * Verriegelt wird über denselben einen Riegel wie überall (`chooseLock`):
   * Die vorher gewählte Tür geht dabei auf, und diese hier hält acht bis zehn
   * Sekunden, wenn das Monster sie nicht vorher aufzieht.
   */
  private stepSeal(gap: number): void {
    const here = this.player.space;
    if (here !== this.wasSpace) {
      const hunted = this.haunt.monsterOn && (this.memory.mode === 'hunt' || gap < SEAL_RANGE);
      const door = hunted ? this.doorBetween(this.wasSpace, here) : null;
      if (door) askSeal(this.seal, door.id, this.haunt.time, this.players, () => this.rng.next());
      this.wasSpace = here;
    }
    const relayed = this.seal.relayed;
    const due = dueSeal(this.seal, this.haunt.time);
    if (!due || this.haunt.shut.includes(due)) return;
    const door = leafDoors(this.house).find((one) => one.id === due);
    // Zu spät ist zu spät: Wer schon durch ist, wird nicht mehr ausgesperrt.
    if (!door || this.monster.space === this.player.space) return;
    this.haunt.shut = chooseLock(this.locks, this.haunt.shut, due, this.haunt.time, () =>
      this.rng.next(),
    );
    this.wave('', doorCentre(door), NOISE.door, 'door');
    this.events.push({
      kind: 'good',
      text: relayed
        ? 'Die Zentrale verriegelt die Tür hinter dir.'
        : 'Die Tür fällt hinter dir zu.',
    });
  }

  /** Die Tür zwischen zwei Räumen, die dem Spieler am nächsten liegt. */
  private doorBetween(a: string, b: string): HouseDoor | null {
    let best: HouseDoor | null = null;
    let near = Infinity;
    for (const door of leafDoors(this.house)) {
      const far = door.b ?? COMMAND;
      if (!((door.a === a && far === b) || (door.a === b && far === a))) continue;
      const at = doorCentre(door);
      const d = Math.hypot(at.x - this.player.x, at.z - this.player.z);
      if (d < near) {
        near = d;
        best = door;
      }
    }
    return best;
  }

  /**
   * **Eine fertige Reparatur ist ein Ereignis der Station**, kein stiller
   * Haken: Die Konsole fährt hoch, die Sicherung fällt, im Modul flackert es.
   * Das Monster weiß danach, wo eben jemand stand — das steht im Gedächtnis
   * als Aufruhr und nicht als Sichtung (`disturbed`) — und legt für
   * `MonsterTuning.rush` Sekunden los. Gezählt wird am Stand (`done`), damit
   * es auch die Konsole trifft, die das Schiff repariert hat, während diese
   * Runde sein Rechenkern ist (`flatKernel.ts`).
   */
  private noticeRepairs(): void {
    const done = this.haunt.done;
    if (done.length <= this.repaired) {
      this.repaired = done.length;
      return;
    }
    for (const entry of done.slice(this.repaired)) {
      const room = repairRoom(this.house, entry);
      if (!room) continue;
      this.brain.disturbed(room, this.graph.centre(room), this.haunt.time);
      this.routine.hurry(this.tuning.monster.rush);
    }
    this.repaired = done.length;
  }

  /** Ein Geräusch des Spielers für die Ohren des Monsters (`audio/cues.ts`, `NOISE`) — und als Welle auf die Karte. */
  noise(at: FloorPoint, loudness: number, cause: MapNoiseCause = 'interact'): void {
    this.pendingNoises.push({ at: { x: at.x, z: at.z }, loudness });
    this.wave(PLAYER_ID, at, loudness, cause);
  }

  /** Eine Welle auf der Karte: wer, wo, wie weit (`reachOf`), wann. */
  private wave(by: string, at: FloorPoint, loudness: number, cause: MapNoiseCause): void {
    this.noiseLog.push({
      id: `n${this.noiseSerial++}`,
      by,
      at: { x: at.x, z: at.z },
      radius: reachOf(loudness),
      cause,
      since: this.haunt.time,
    });
  }

  /** Der Würfel der Runde — damit ein Steuer denselben Zufall nimmt wie sie. */
  roll(): number {
    return this.rng.next();
  }

  /** Der Alarm des Monsters — für Anzeigen und Tests. */
  get threat(): Readonly<ThreatState> {
    return this.memory;
  }

  /**
   * **Der letzte Beschluss des Monsters** — Haltung, Ziel, Tempo und, wenn ein
   * Gedächtnis dabei ist, sein `insight` (`monsterRoutine.ts`). Für Anzeigen
   * und für Tests, die den Unterschied zwischen „steht absichtlich" und
   * „hängt an einer Wand" brauchen; von außen nur zu lesen.
   */
  /** Was das Monster gerade anstellt (`haunt.ts`) — für das Flackern der Lampen im Schiff. */
  get spook(): Readonly<Spook> {
    return this.spooking;
  }

  /**
   * **Neue Gewichte im laufenden Spiel** (`botTuning.ts`): Die Routine des
   * Monsters bekommt sie sofort; Tempo, Sicht und Gehör lesen sie ohnehin je
   * Bild aus `tuning`. Die 3D-Welt ruft das, wenn der Test-Regler bewegt wird.
   */
  retune(tuning: BotTuning): void {
    this.tuning = tuning;
    this.routine.retune(tuning.monster);
  }

  get decided(): Readonly<RoutineOutput> | null {
    return this.decision;
  }

  /** Die Rasterwegsuche mit Cursor auf der Route des Monsters (`navmesh/flatNavigator.ts`) — für Tests und die Karte. */
  get navigator(): FlatNavigator {
    return this.walk.navigator;
  }

  private hit(text: string): void {
    const crew = this.haunt.crew;
    // **Wer getroffen wird, blutet** (`rules/blood.ts`) — und zieht dem
    // Monster für die nächsten zwei Minuten eine Fährte hinterher.
    wound(this.blood, this.haunt.time);
    // **Der Schub nach dem Treffer** (`mission.HIT_BURST`). Wer getroffen
    // wird, steht sonst genau dort, wo ihn der nächste Schlag trifft: Die drei
    // Sekunden Unverwundbarkeit nützen nichts, wenn man sie im Griff des
    // Monsters absteht. Anderthalb Sekunden Sprint, die keine Puste kosten —
    // gerade genug für eine Tür.
    grantBurst(this.stamina);
    // **Und das Monster hält inne** (`monsterRoutine.rest`, `mission.HIT_LULL`):
    // Der Schub nützt nichts, wenn das Vieh den Sprint mitläuft.
    this.routine.rest(HIT_LULL, { x: this.monster.x, z: this.monster.z }, this.monster.space);
    if (crew.hp <= 0) {
      this.haunt.phase = 'lost';
      this.events.push({ kind: 'bad', text: 'MISSION GESCHEITERT · Anzug zerstört.' });
    } else this.events.push({ kind: 'bad', text: `${text} Anzug ${crew.hp}/3.` });
  }

  /** Das Feld nur aus Lampen und Taschenlampe — wofür das Monster Augen hat. */
  private lightOnly(): Pick<VisibilityField, 'lit' | 'self'> {
    return { lit: this.field.lit, self: null };
  }

  /**
   * Das Monster geht den Rasterweg der 3D-Welt (`navmesh/flatNavigator.ts`):
   * Wegpunkt für Wegpunkt, mit dem ganzen Zeitschritt über mehrere Punkte
   * hinweg, gleitend an Wänden. Eine gesperrte Tür umgeht es, wenn es einen
   * Umweg gibt; gibt es keinen, führt die Route bis vor die Tür — Holz hält
   * es dort kurz auf, Stahl für immer, dann wählt die Routine irgendwann ein
   * anderes Ziel.
   */
  private moveMonster(decision: RoutineOutput, dt: number, speed: number): void {
    const goal = decision.goal;
    if (!goal || speed <= 0) return;
    const out = this.walk.step(this.monster, goal, this.haunt.time, speed);
    for (const event of out.events) this.doorWorked(event);
    if (out.mode === 'hold' || !out.target) return;
    if (out.mode === 'detour') {
      this.stepMonster(out.target, speed, dt);
      return;
    }
    // Der ganze Zeitschritt wird verbraucht, auch über mehrere Wegpunkte hinweg —
    // die Bogenstützen des Kurvenschleifers liegen enger als ein Schritt.
    let budget = speed * dt;
    let step: FloorPoint | null = out.target;
    for (let hops = 0; hops < 16 && budget > 1e-3 && step; hops++) {
      const fromX = this.monster.x,
        fromZ = this.monster.z;
      this.stepMonster(step, budget / dt, dt);
      const moved = Math.hypot(this.monster.x - fromX, this.monster.z - fromZ);
      if (moved < 1e-4) break;
      budget -= moved;
      step = this.walk.next(this.monster);
    }
  }

  /** Was das Monster an einer gesperrten Tür getan hat — Meldung und Welle (`monster/monsterWalk.ts`). */
  private doorWorked(event: WalkEvent): void {
    const at = doorCentre(event.door);
    if (event.kind === 'splinter') {
      this.events.push({ kind: 'warn', text: 'Holz splittert.' });
      this.wave(MONSTER_ID, at, NOISE.slam, 'slam');
    } else if (event.kind === 'give') {
      this.events.push({ kind: 'warn', text: 'Ein Riegel gibt nach.' });
      this.wave(MONSTER_ID, at, NOISE.slam, 'slam');
    } else this.wave(MONSTER_ID, at, NOISE.monsterWalk, 'door');
  }

  private stepMonster(step: FloorPoint, speed: number, dt: number): void {
    const dx = step.x - this.monster.x,
      dz = step.z - this.monster.z;
    const distance = Math.hypot(dx, dz);
    if (distance < 1e-3) return;
    this.monster.yaw = Math.atan2(-dx, -dz);
    const travel = Math.min(distance, speed * dt);
    const to = this.cells.move(
      this.closed,
      this.monster,
      (dx / distance) * travel,
      (dz / distance) * travel,
    );
    // **Die Einsatzzentrale betritt es nie.** Die Wegsuche führt es nicht
    // dorthin (seine Karte kennt den Ort nicht), aber ein Schritt, der an der
    // Schleuse entlangschleift, käme trotzdem hinein — und ein Monster in der
    // Zentrale beendet die Runde an dem einen Ort, an dem sie sicher sein soll.
    if (onApron(Math.floor(to.x / TILE), Math.floor(to.z / TILE))) return;
    this.monster.x = to.x;
    this.monster.z = to.z;
    const space = spaceAtMetres(this.house, this.monster, this.monster.space, SPACE_MARGIN);
    if (space && space !== COMMAND) this.monster.space = space.id;
  }

  // --- Knöpfe ---------------------------------------------------------------

  act(action: FlatAction): void {
    if (!this.stepping) return;
    if (action === 'cycle') {
      if (this.tools.length > 1) this.active = (this.active + 1) % this.tools.length;
      this.events.push({ kind: 'info', text: TOOL_LABELS[this.activeTool] ?? this.activeTool });
    } else if (action === 'use') this.use();
    else if (this.chore) {
      // Derselbe Knopf bricht ab: Ein Balken, den man nur durch Weglaufen
      // loswird, ist eine Falle.
      this.events.push({ kind: 'warn', text: `${this.chore.label} abgebrochen.` });
      this.chore = null;
    } else this.interact();
  }

  private use(): void {
    const crew = this.haunt.crew;
    const tool = this.activeTool;
    if (tool) this.noise(this.player, tool === 'flashlight' ? NOISE.light : NOISE.click);
    if (tool === 'flashlight') {
      this.torch = !this.torch;
      this.events.push({ kind: 'info', text: this.torch ? 'Lampe an.' : 'Lampe aus.' });
    } else if (tool === 'medkit') {
      if (crew.hp >= 3) {
        this.events.push({ kind: 'info', text: 'Anzug ist unversehrt.' });
        return;
      }
      crew.hp = Math.min(3, crew.hp + 1);
      this.dropTool('medkit');
      this.events.push({ kind: 'good', text: `Medkit benutzt · Anzug ${crew.hp}/3.` });
    } else if (tool === 'radar') {
      if (!this.haunt.monsterOn) {
        this.events.push({ kind: 'info', text: 'Radar: kein Kontakt.' });
        return;
      }
      const dx = this.monster.x - this.player.x,
        dz = this.monster.z - this.player.z;
      this.radarPing = 3;
      this.events.push({
        kind: 'warn',
        text: `Radar: Kontakt ${Math.round(Math.hypot(dx, dz))} m ${compass(dx, dz)}.`,
      });
    } else if (tool === 'xray') {
      // Das Röntgengerät zeigt Inhalte, keine Kisten: Leere meldet es nicht.
      const open = this.cargo.filter(
        (c) => !c.empty && !crew.inventory.includes(c.key) && !this.haunt.done.includes(c.key),
      );
      const near = open
        .map((c) => ({ c, d: Math.hypot(c.at.x - this.player.x, c.at.z - this.player.z) }))
        .sort((p, q) => p.d - q.d)[0];
      // **Das Röntgen nennt die Kiste, nie ihren Inhalt.** Es ist der
      // technische Ausweg des Technikers, wenn niemand am Archiv sitzt oder
      // der Archivar schweigt — und es soll ihm dieselbe Auskunft geben wie
      // ein Mensch am Telefon: Kennzeichen und Raum.
      this.events.push({
        kind: 'info',
        text: near
          ? `Röntgen: ${near.c.mark} in ${Math.round(near.d)} m (${roomName(this.house, near.c.roomId)}).`
          : 'Röntgen: keine Fracht mehr.',
      });
    }
  }

  private dropTool(id: string): void {
    const index = this.tools.indexOf(id);
    if (index >= 0) this.tools.splice(index, 1);
    const held = this.haunt.crew.inventory.indexOf(id);
    if (held >= 0) this.haunt.crew.inventory.splice(held, 1);
    this.active = Math.min(this.active, this.tools.length - 1);
  }

  /** Ob das Radar gerade das Monster zeigt. */
  get radarActive(): boolean {
    return this.radarPing > 0;
  }

  private nearest(): {
    kind: MapItem['kind'] | 'door' | 'light';
    id: string;
    label: string;
    at: FloorPoint;
  } | null {
    const crew = this.haunt.crew;
    if (crew.hidden) {
      const locker = this.lockers.find((l) => l.id === crew.hidden)!;
      return { kind: 'locker', id: locker.id, label: 'Schrank verlassen', at: locker.at };
    }
    const candidates: Array<{
      kind: MapItem['kind'] | 'door' | 'light';
      id: string;
      label: string;
      at: FloorPoint;
    }> = [];
    for (const cargo of this.cargo) {
      if (crew.inventory.includes(cargo.key) || this.haunt.done.includes(cargo.key)) continue;
      candidates.push({
        kind: 'cargo',
        id: cargo.id,
        label: !crew.opened.includes(cargo.id)
          ? `${cargo.mark} öffnen`
          : cargo.empty
            ? `${cargo.mark} durchsuchen`
            : `${cargo.label} nehmen`,
        at: cargo.at,
      });
    }
    for (const console of this.consoles)
      if (!this.haunt.done.includes(console.repair.itemId))
        candidates.push({
          kind: 'console',
          id: console.id,
          label: console.repair.title,
          at: console.at,
        });
    for (const locker of this.lockers)
      if (this.rules.cabinUsable(locker.id))
        candidates.push({
          kind: 'locker',
          id: locker.id,
          label: 'Im Schrank verstecken',
          at: locker.at,
        });
    for (const door of leafDoors(this.house)) {
      const locked = this.haunt.shut.includes(door.id);
      candidates.push({
        kind: 'door',
        id: door.id,
        label: locked ? 'Tür entriegeln' : 'Tür verriegeln',
        at: doorCentre(door),
      });
    }
    for (const room of spacesOf(this.house))
      candidates.push({
        kind: 'light',
        id: room.id,
        label: this.haunt.lit.includes(room.id) ? 'Licht aus' : 'Licht an',
        at: this.graph.centre(room.id),
      });
    let best: (typeof candidates)[number] | null = null;
    let bestDistance = REACH;
    const heading = headingOf(this.player.yaw);
    for (const candidate of candidates) {
      const dx = candidate.at.x - this.player.x,
        dz = candidate.at.z - this.player.z;
      const distance = Math.hypot(dx, dz);
      const reach =
        candidate.kind === 'door' ? REACH * 1.1 : candidate.kind === 'light' ? REACH * 0.8 : REACH;
      if (distance > reach) continue;
      // Was vor einem liegt, gewinnt gegen das, was hinter einem liegt.
      const facing = distance < 0.3 ? 0 : -(dx * heading.x + dz * heading.z) / distance;
      const score = distance + facing * 0.5;
      if (score < bestDistance) {
        bestDistance = score;
        best = candidate;
      }
    }
    return best;
  }

  /**
   * **Den laufenden Handgriff weiterzählen** (`rules/chore.ts`): fertig,
   * abgebrochen oder noch dabei. Abgebrochen wird, wer sich von der Stelle
   * rührt — Umschauen ist erlaubt, Weggehen nicht —, und auch, wer sich
   * währenddessen versteckt oder ein Rätsel aufschlägt.
   */
  private stepChore(dt: number): void {
    const chore = this.chore;
    if (!chore) return;
    const step = stepChore(chore, dt, this.player, !this.haunt.crew.hidden && !this.puzzle);
    if (step.kind === 'running') {
      this.chore = step.chore;
      return;
    }
    this.chore = null;
    if (step.kind === 'broken') {
      this.events.push({ kind: 'warn', text: `${chore.label} abgebrochen.` });
      return;
    }
    const cargo = this.cargo.find((one) => one.id === chore.id);
    if (!cargo) return;
    const crew = this.haunt.crew;
    if (!crew.opened.includes(cargo.id)) crew.opened.push(cargo.id);
    // Der Deckel schlägt auf — und das hört man (`audio/cues.ts`).
    this.noise(cargo.at, NOISE.interact, 'interact');
    this.events.push({ kind: 'info', text: `${cargo.mark} geöffnet.` });
  }

  /**
   * **Der Handgriff, an dem gerade gearbeitet wird** — für den Ladebalken und
   * für alle, die währenddessen still halten müssen (`rules/technicianBot.ts`).
   */
  get busy(): Readonly<Chore> | null {
    return this.chore;
  }

  /** Wie weit der Balken ist, von 0 bis 1 — `0`, wenn nichts läuft. */
  get busyProgress(): number {
    return this.chore ? choreProgress(this.chore) : 0;
  }

  private interact(): void {
    const crew = this.haunt.crew;
    const near = this.nearest();
    if (!near) {
      this.events.push({ kind: 'info', text: 'Hier ist nichts.' });
      return;
    }
    // Hantieren macht Lärm — eine Tür mehr als ein Schalter (`audio/cues.ts`).
    this.noise(
      near.at,
      near.kind === 'door' ? NOISE.door : near.kind === 'light' ? NOISE.light : NOISE.interact,
      near.kind === 'door' ? 'door' : 'interact',
    );
    if (near.kind === 'locker') {
      if (crew.hidden) {
        crew.hidden = '';
        this.events.push({ kind: 'info', text: 'Schrank verlassen.' });
      } else {
        crew.hidden = near.id;
        this.player.x = near.at.x;
        this.player.z = near.at.z;
        this.events.push({ kind: 'info', text: 'Versteckt. Still bleiben.' });
      }
      return;
    }
    if (near.kind === 'cargo') {
      const cargo = this.cargo.find((c) => c.id === near.id)!;
      if (!crew.opened.includes(cargo.id)) {
        // **Aufklappen kostet Zeit** (`rules/chore.ts`). Erst wenn der Balken
        // durch ist, steht der Deckel offen; ein Schritt dazwischen bricht ab.
        this.chore = {
          kind: 'cargo',
          id: cargo.id,
          label: `${cargo.mark} öffnen`,
          at: { x: this.player.x, z: this.player.z },
          left: CARGO_OPEN_SECONDS,
          total: CARGO_OPEN_SECONDS,
        };
        return;
      }
      // **Die leere Kiste kostet zwei Griffe**, nicht einen: aufmachen,
      // hineinsehen. Erst danach ist sie erledigt und steht dem Techniker
      // nicht mehr als Ziel im Weg.
      if (cargo.empty) {
        crew.inventory.push(cargo.key);
        this.events.push({ kind: 'info', text: 'Leer.' });
        return;
      }
      // **Eine Hand, ein Ersatzteil** (`rules/archiveGoals.ts`). Die Kiste
      // bleibt offen und unerledigt: Wer zurückkommt, findet sie so vor, wie
      // er sie verlassen hat — und wer alles einsammeln wollte, muss statt
      // dessen laufen.
      const part = this.house.tasks.some((t) => t.id === cargo.loot);
      if (part && !canCarryPart(this.house, this.haunt)) {
        this.events.push({ kind: 'warn', text: fullHandsText(this.house, this.haunt) });
        return;
      }
      crew.inventory.push(cargo.loot);
      if (part) {
        this.haunt.taken.push(cargo.loot);
        this.events.push({ kind: 'good', text: `${cargo.label} mitgenommen.` });
      } else {
        if (!this.tools.includes(cargo.loot)) this.tools.push(cargo.loot);
        this.events.push({ kind: 'good', text: `${cargo.label} eingesteckt.` });
      }
      return;
    }
    if (near.kind === 'console') {
      const console = this.consoles.find((c) => c.id === near.id)!;
      if (!crew.inventory.includes(console.repair.itemId)) {
        this.events.push({
          kind: 'warn',
          text: `Abdeckung verriegelt: ${console.repair.item} fehlt.`,
        });
        return;
      }
      puzzleFor(crew, console.repair.id).open = true;
      this.puzzle = console.repair;
      return;
    }
    if (near.kind === 'door') {
      this.events.push({ kind: 'info', text: this.lockDoor(near.id) });
      return;
    }
    if (near.kind === 'light') this.events.push({ kind: 'info', text: this.switchLight(near.id) });
  }

  /**
   * **Eine Tür gewollt sperren oder freigeben** — vor Ort oder von der
   * Schalttafel aus: Gewollt gesperrt ist immer nur eine, sie hält bis zum
   * Ablauf, und die nächste wartet so lange (`rules/doorLocks.ts`).
   * Zugefallene darf man jederzeit freigeben.
   *
   * @returns die Zeile für den Spieler.
   */
  lockDoor(id: string): string {
    const door = leafDoors(this.house).find((d) => d.id === id);
    if (!door || !this.stepping) return '';
    // **Auch im Test mit Frist** — derselbe Riegel wie in der Mission: Er
    // hält, bis er fällt, eine zweite Tür wartet, und eine eben freigewordene
    // bleibt einen Moment frei (`rules/doorLocks.ts`). Wer im Test ohne Frist
    // schalten durfte, sah nie den Balken und lernte ein anderes Spiel.
    const out = toggleLock(this.locks, this.haunt.shut, id, this.haunt.time, () => this.rng.next());
    this.haunt.shut = out.shut;
    if (out.blocked) return LOCK_BLOCK_TEXT[out.blocked];
    return out.locked ? 'Tür verriegelt.' : 'Tür entriegelt.';
  }

  /**
   * **Das Licht eines Raums umlegen** — vor Ort oder von der Schalttafel aus.
   *
   * Es geht durch dieselbe Buchführung wie im Headset (`rules/lamps.ts`):
   * höchstens `LAMP_BUDGET` Lampen gleichzeitig, die dritte macht die älteste
   * aus, und keine brennt länger als `LAMP_RANGE`. Vorher schrieb diese
   * Methode nur in die Liste der hellen Räume, und die 2D-Runde hatte damit
   * ein anderes Licht als das Spiel, für das sie der Prüfstand ist.
   */
  switchLight(roomId: string): string {
    if (!this.stepping) return '';
    // Im Test ist Licht ein Schalter und kein Budget: an oder aus, für immer.
    if (!this.live) {
      const on = this.haunt.lit.includes(roomId);
      this.haunt.lit = on
        ? this.haunt.lit.filter((one) => one !== roomId)
        : [...this.haunt.lit, roomId];
      return on ? 'Licht aus.' : 'Licht an.';
    }
    const out = switchLamp(this.lampBook, this.haunt.lit, roomId, this.haunt.time, () =>
      this.rng.next(),
    );
    this.haunt.lit = out.lit;
    if (!out.on) return 'Licht aus.';
    return out.dropped ? 'Licht an · dafür geht ein anderes aus.' : 'Licht an.';
  }

  /**
   * **Die Ziele des Technikers, in Reihenfolge**: je Reparatur erst das
   * Ersatzteil, dann die Konsole; sind alle drei erledigt, die Zentrale.
   * Das erste ist das nächste — das mit dem Dreieck am Bildrand.
   */
  objectives(): MapGoal[] {
    const crew = this.haunt.crew;
    const out: MapGoal[] = [];
    if (this.precision === 'none') return out;
    for (const repair of repairsFor(this.house)) {
      if (this.haunt.done.includes(repair.itemId)) continue;
      const cargo = this.cargo.find((c) => c.loot === repair.itemId);
      const console = this.consoles.find((c) => c.repair.id === repair.id);
      if (cargo && !crew.inventory.includes(repair.itemId))
        out.push({
          id: cargo.id,
          at: { ...cargo.at },
          label: cargo.label,
          next: false,
          kind: 'crate',
          precision: 'exact',
        });
      else if (console)
        out.push({
          id: console.id,
          at: { ...console.at },
          label: repair.title,
          next: false,
          kind: 'console',
          precision: 'exact',
        });
    }
    if (!out.length)
      out.push({
        id: 'van',
        at: { x: COMMAND_HOME.x, z: COMMAND_HOME.z },
        label: 'Zurück zur Zentrale',
        next: false,
        kind: 'van',
        precision: 'exact',
      });
    out[0]!.next = true;
    return out;
  }

  /** Der Weg, den das Monster gerade geht — leer, wenn ein Spieler es steuert oder es steht. */
  monsterRoute(): MapPoint[] {
    if (!this.haunt.monsterOn || this.driver?.active() || this.ventRide.busy) return [];
    const points = this.navigator.remaining;
    if (!points.length) return [];
    return [{ x: this.monster.x, z: this.monster.z }, ...points.map((p) => ({ x: p.x, z: p.z }))];
  }

  /**
   * Der Weg des Spielers zum nächsten Ziel — dieselbe Wegsuche wie die des
   * Monsters (`navmesh/flatNavigator.ts`), mit dem Radius des Spielers; nur
   * gerechnet, wenn jemand ihn sehen will, und nur so oft, wie der Navigator
   * selbst neu plant.
   */
  playerRoute(): MapPoint[] {
    const goal = this.objectives()[0];
    if (!goal || this.haunt.crew.hidden) return [];
    this.playerNav ??= new FlatNavigator(this.house, this.graph, PLAYER_RADIUS);
    this.playerNav.aim(this.player, goal.at, this.haunt.shut, this.haunt.time);
    const points = this.playerNav.remaining.map((p) => ({ x: p.x, z: p.z }));
    return [{ x: this.player.x, z: this.player.z }, ...points];
  }

  // --- Rätsel --------------------------------------------------------------

  /** Ein Zug im offenen Rätsel. Gelöst heißt: repariert und zu. */
  solve(action: PuzzleAction): { solved: boolean; wrong: boolean } {
    const repair = this.puzzle;
    if (!repair) return { solved: false, wrong: true };
    const puzzle = puzzleFor(this.haunt.crew, repair.id);
    const outcome = applyPuzzle(repair, puzzle, action);
    this.noise(this.player, NOISE.click);
    if (outcome.solved && puzzleSolved(repair, puzzle)) {
      this.haunt.done.push(repair.itemId);
      // Das Monster erfährt es im nächsten Schritt (`noticeRepairs`) — auf
      // demselben Weg wie von einer Konsole, die das Schiff repariert hat.
      const held = this.haunt.crew.inventory.indexOf(repair.itemId);
      if (held >= 0) this.haunt.crew.inventory.splice(held, 1);
      this.puzzle = null;
      this.events.push({
        kind: 'good',
        text:
          this.haunt.done.length >= 3
            ? `${repair.title}: erledigt. Zurück zur Zentrale!`
            : `${repair.title}: erledigt (${this.haunt.done.length}/3).`,
      });
    }
    return outcome;
  }

  closePuzzle(): void {
    this.puzzle = null;
  }

  /** Nur für Tests: den Spieler irgendwohin stellen, wo man stehen darf. */
  /** Ob an dieser Stelle jemand stehen kann — Raum, Vorplatz oder Tür, nicht Wand und nicht Möbel. */
  canStand(at: FloorPoint): boolean {
    return this.cells.canStand(this.closed, at);
  }

  place(at: FloorPoint): boolean {
    if (!this.cells.canStand(this.closed, at)) return false;
    this.player.x = at.x;
    this.player.z = at.z;
    const space = spaceAtMetres(this.house, at);
    this.player.space = space === null ? this.player.space : space === COMMAND ? COMMAND : space.id;
    this.snapshotCache = null;
    return true;
  }

  /** Die Zielpunkte, in Reihenfolge — für Tests und die Bot-Vorschau. */
  jobs(): Array<{ kind: 'cargo' | 'console'; id: string; at: FloorPoint; roomId: string }> {
    const out: Array<{ kind: 'cargo' | 'console'; id: string; at: FloorPoint; roomId: string }> =
      [];
    for (const repair of repairsFor(this.house)) {
      const cargo = this.cargo.find((c) => c.loot === repair.itemId);
      const console = this.consoles.find((c) => c.repair.id === repair.id);
      if (cargo) out.push({ kind: 'cargo', id: cargo.id, at: cargo.at, roomId: cargo.roomId });
      if (console)
        out.push({ kind: 'console', id: console.id, at: console.at, roomId: console.roomId });
    }
    return out;
  }
}

function monsterBase(kind: MonsterKind): number {
  return MONSTERS.find((m) => m.id === kind)?.speed ?? 2.8;
}

function farthest(graph: StationGraph, from: FloorPoint): string {
  let best = graph.rooms[0] ?? graph.spaces[0]!;
  let far = -1;
  for (const id of graph.rooms) {
    const centre = graph.centre(id);
    const distance = Math.hypot(centre.x - from.x, centre.z - from.z);
    if (distance > far) {
      far = distance;
      best = id;
    }
  }
  return best;
}

function roomName(spec: HouseSpec, id: string): string {
  return spacesOf(spec).find((room) => room.id === id)?.name ?? id;
}

/**
 * Wie der Inhalt einer Kiste heißt — und bei einer leeren die Kiste selbst:
 * „Leer" ist kein Name, „Kiste 2 · blau" schon, und auf der Karte steht ein
 * Name.
 */
function lootName(house: HouseSpec, slot: CargoSlot): string {
  const loot = slot.loot;
  if (loot.kind === 'part')
    return house.tasks.find((t) => t.id === loot.taskId)?.label ?? loot.taskId;
  if (loot.kind === 'tool') return TOOL_LABELS[loot.tool] ?? loot.tool;
  return cargoLabel(slot);
}

function compass(dx: number, dz: number): string {
  const angle = Math.atan2(dx, -dz);
  const names = [
    'nördlich',
    'nordöstlich',
    'östlich',
    'südöstlich',
    'südlich',
    'südwestlich',
    'westlich',
    'nordwestlich',
  ];
  const index = Math.round(((angle + Math.PI * 2) % (Math.PI * 2)) / (Math.PI / 4)) % 8;
  return names[index]!;
}
